mapper.select:
select *
from user_violation_record
where 1 = 1

    and user_id = #{userId}


    and reservation_id = #{reservationId}


    and violation_type = #{violationType}

order by id desc
limit #{offset}, #{pageSize}

select count(*)
from user_violation_record
where 1 = 1

    and user_id = #{userId}


    and reservation_id = #{reservationId}


    and violation_type = #{violationType}

select *
from user_violation_record
where user_id = #{userId}

    and violation_type = #{violationType}




            and score_change  >  0


            and score_change  <  0


            and score_change = 0



order by id desc
limit #{offset}, #{pageSize}

select count(*) from user_violation_record where user_id = #{userId}
and violation_type = #{violationType}
and score_change > 0
and score_change < 0
and score_change = 0

select exists(
    select 1
    from user_violation_record
    where reservation_id = #{reservationId}
      and violation_type = #{violationType}
)

select exists(
    select 1
    from user_violation_record
    where reservation_id = #{reservationId}
)

select violation_type as name, count(*) as count
from user_violation_record v
left join sys_user u on v.user_id = u.id
where 1 = 1

    and date(v.created_at)  >=  #{startDate}


    and date(v.created_at)  <=  #{endDate}


    and u.department_id = #{departmentId}


    and violation_type = #{violationType}

group by violation_type

mapper.sql:
from user_violation_record v join sys_user u on u.id = v.user_id left join lab_reservation r on r.id = v.reservation_id left join lab l on l.id = r.lab_id left join ( select s.reservation_id, min(timestamp(s.reservation_date, p.start_time)) as firstStartAt, min(s.reservation_date) as firstDate from lab_reservation_slot s join class_period p on p.id = s.period_id where s.slot_status = 1 group by s.reservation_id ) slot on slot.reservation_id = v.reservation_id where u.deleted = 0 and u.department_id = #{departmentId} and coalesce(slot.firstStartAt, v.created_at) >= #{startDate} and coalesce(slot.firstStartAt, v.created_at) < date_add(#{endDate}, interval 1 day)
and l.lab_type = #{labType}
and r.lab_id = #{labId}
and (r.id is not null and r.status = #{status})
and (r.id is not null and r.reservation_type = #{reservationType})

mapper.select:
select u.real_name as realName, u.user_no as userNo, case when exists ( select 1 from sys_user_role ur join sys_role role on role.id = ur.role_id where ur.user_id = u.id and role.role_code in ('TEACHER', 'ROLE_TEACHER') ) then '教师' else '学生' end as userRole, u.credit_score as creditScore, v.violation_type as violationType, v.score_change as scoreChange, coalesce(slot.firstStartAt, v.created_at) as violationTime, r.reservation_no as reservationNo, total.totalViolationCount as totalViolationCount, v.remark as remark from user_violation_record v join sys_user u on u.id = v.user_id left join lab_reservation r on r.id = v.reservation_id left join lab l on l.id = r.lab_id left join ( select s.reservation_id, min(timestamp(s.reservation_date, p.start_time)) as firstStartAt from lab_reservation_slot s join class_period p on p.id = s.period_id where s.slot_status = 1 group by s.reservation_id ) slot on slot.reservation_id = v.reservation_id left join ( select v1.user_id, count(*) as totalViolationCount from user_violation_record v1 join sys_user u1 on u1.id = v1.user_id where u1.deleted = 0 and u1.department_id = #{departmentId} group by v1.user_id ) total on total.user_id = v.user_id where u.deleted = 0 and u.department_id = #{departmentId} and coalesce(slot.firstStartAt, v.created_at) >= #{startDate} and coalesce(slot.firstStartAt, v.created_at) < date_add(#{endDate}, interval 1 day)
and l.lab_type = #{labType}
and r.lab_id = #{labId}
and (r.id is not null and r.status = #{status})
and (r.id is not null and r.reservation_type = #{reservationType})
order by coalesce(slot.firstStartAt, v.created_at) desc, v.id desc limit #{limit}
